def score(c,s):
 H,S,K,T=c.split("\n")
 E=list(S)
 for i,q in enumerate(S):
  if q=="x"and H[i]=="."and K[i]==".":
   j=i;E[i]="-"
   while H[j]==".":
    j+=1+(S[j+1]=="|");E[j]="-"
   E[j]="x"
 f=lambda z:re.sub("[^x.-]","",z)
 R=[y for y in map(f,s.split("\n"))if y]
 return int(R==[f(H),f("".join(E)),f(K)])
